const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Shanghai geometry
  const shanghai = ee.Geometry.Point([121.47, 31.23]).buffer(50000); // 50km buffer

  // Define time periods
  const feb_start = '2020-02-10';
  const feb_end = '2020-02-25';
  const apr_start = '2020-04-20';
  const apr_end = '2020-05-12';

  // Get Sentinel-5P TROPOMI NO2 data
  const tropomi = ee.ImageCollection('COPERNICUS/S5P/NRTI_L3_NO2')
    .select('tropospheric_NO2_column_number_density');

  // February 2020 collection
  const feb_col = tropomi
    .filterDate(feb_start, feb_end)
    .filterBounds(shanghai);

  // April-May 2020 collection
  const apr_col = tropomi
    .filterDate(apr_start, apr_end)
    .filterBounds(shanghai);

  const feb_size = feb_col.size().getInfo();
  const apr_size = apr_col.size().getInfo();

  print('February 10-25, 2020 images: ' + feb_size);
  print('April 20-May 12, 2020 images: ' + apr_size);

  // Check if collections are empty
  if (feb_size === 0 || apr_size === 0) {
    print('Missing data for one or both periods.');
    print('C1');
    return;
  }

  // Calculate mean NO2 for February
  const feb_mean_img = feb_col.mean();
  const feb_stats = feb_mean_img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: shanghai,
    scale: 5600,
    maxPixels: 1e9
  });
  const feb_mean = feb_stats.get('tropospheric_NO2_column_number_density').getInfo();

  // Calculate mean NO2 for April-May
  const apr_mean_img = apr_col.mean();
  const apr_stats = apr_mean_img.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: shanghai,
    scale: 5600,
    maxPixels: 1e9
  });
  const apr_mean = apr_stats.get('tropospheric_NO2_column_number_density').getInfo();

  // Check for valid results
  if (feb_mean === null || apr_mean === null || isNaN(feb_mean) || isNaN(apr_mean)) {
    print('Calculation resulted in null or NaN.');
    print('C3');
    return;
  }

  // Check for pixel counts
  const feb_count = feb_mean_img.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: shanghai,
    scale: 5600,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  const apr_count = apr_mean_img.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: shanghai,
    scale: 5600,
    maxPixels: 1e9
  }).get('tropospheric_NO2_column_number_density').getInfo();

  if (feb_count === 0 || apr_count === 0) {
    print('No valid pixels after processing.');
    print('C2');
    return;
  }

  print('Feb 10-25 mean NO2: ' + feb_mean.toFixed(4) + ' mol/m²');
  print('Apr 20-May 12 mean NO2: ' + apr_mean.toFixed(4) + ' mol/m²');
  print('Feb pixels: ' + feb_count + ', Apr pixels: ' + apr_count);

  // Determine if NO2 increased
  if (apr_mean > feb_mean) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
